-- Actual management-function golden values captured from the reviewed source.
-- Expected values were generated by the JS functions, not this SQL port.
-- The server uses authoritativeOnly=true: no clock-dependent fallback lessons.
-- Synthetic pure-function assertions; runtime execution is a required PG gate.
begin;
select no_plan();
set local timezone='Asia/Seoul';
set local statement_timeout='30s';
create temp table withdrawal_formula_vectors(id text primary key,class_input jsonb,selected_date date,management_expected jsonb,server_expected jsonb,policy text);
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(class_input,selected_date),server_expected,id||': '||policy)
 from withdrawal_formula_vectors order by id;
set local timezone='UTC';
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(class_input,selected_date),server_expected,'UTC parity: '||id)
 from withdrawal_formula_vectors where id in('cross-month-exact-billing-id','same-date-distinct-ids-count-both','gap-exactly-62-days');
select is(dashboard_private.withdrawal_hours_string_v1(1.25::double precision),'1.3','positive binary64 tie matches Math.round, not ties-to-even');
select is(dashboard_private.withdrawal_hours_string_v1(0::double precision),'0','formatter preserves explicit zero');
select throws_ok($q$select dashboard_private.withdrawal_hours_string_v1('NaN'::double precision)$q$,'22023','withdrawal_hours_unrepresentable','NaN is never formatted as a quantity');
select throws_ok($q$select dashboard_private.withdrawal_hours_string_v1(999999.99::double precision)$q$,'22023','withdrawal_hours_unrepresentable','rounding overflow cannot be silently stored');
select throws_ok($q$select dashboard_private.calculate_teacher_withdrawal_hours_v1('{}','not-a-date'::date)$q$,'22007',null,'malformed selected date is rejected by the typed SQL boundary');
select throws_ok($q$select dashboard_private.calculate_teacher_withdrawal_hours_v1('{}','2026-11-99'::date)$q$,'22008',null,'invalid calendar selection cannot become a different day');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 '{"schedule":"월수 19:30~21:30","schedule_plan":{"sessions":[{"date":"2026-11-99","hours":2}]}}','2026-11-04'),
 '{"completed_lesson_hours":"","four_week_lesson_hours":""}'::jsonb,'invalid saved calendar date makes the snapshot unknown');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 '{"schedule_plan":{"sessions":[{"date":"2026-11-04","hours":1000000}]}}','2026-11-04'),
 '{"completed_lesson_hours":"","four_week_lesson_hours":""}'::jsonb,'calculated numeric(8,2) overflow is unknown, never truncated');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 jsonb_build_object('schedule_plan',jsonb_build_object('sessions',jsonb_build_array(jsonb_build_object('date','2026-11-04','hours',v)))),'2026-11-04'),
 '{"completed_lesson_hours":"","four_week_lesson_hours":""}'::jsonb,'unsupported explicit duration is unknown: '||v::text)
 from (values ('true'::jsonb),('["2"]'::jsonb),('{"private":"canary"}'::jsonb),('"1e2"'::jsonb)) unsupported(v);
select ok(not has_function_privilege('authenticated','dashboard_private.withdrawal_first_scalar_v1(jsonb,text[])','EXECUTE'),'normalizer is private');
select ok(not has_function_privilege('authenticated','dashboard_private.withdrawal_hours_string_v1(double precision)','EXECUTE'),'formatter is private');
select ok(not has_function_privilege('anon','dashboard_private.calculate_teacher_withdrawal_hours_v1(jsonb,date)','EXECUTE'),'anonymous calculation entry is private');
-- Unsupported numeric metadata is deliberately unknown.
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 '{"schedule":"월수19~21","schedule_plan":{"sessions":[{"date":"2026-11-02","sessionNumber":"0x1"},{"date":"2026-11-04","sessionNumber":2}]}}','2026-11-04'),
 '{"completed_lesson_hours":"","four_week_lesson_hours":""}'::jsonb,'unsupported numeric metadata yields unknown, not an invented cycle');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 '{"schedule":"월수19~21","schedule_plan":{"sessions":[{"date":"2026-11-02","sessionNumber":1,"state":"active","hours":2},{"date":"2026-11-04","sessionNumber":2,"state":"active\n","hours":2}]}}','2026-11-04'),
 '{"completed_lesson_hours":"4","four_week_lesson_hours":"16"}'::jsonb,'state trailing newline retains its counted meaning');
select is(dashboard_private.withdrawal_trim_v1(U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFFactive\FEFF\00A0'),'active',
 'ECMAScript trim set applies equally to state, IDs, labels and numeric metadata');
select is(dashboard_private.withdrawal_metadata_number_v1(to_jsonb(U&'\000B\000C'::text)),0::double precision,'vertical tab and form feed metadata match Number whitespace zero');
select is(dashboard_private.withdrawal_metadata_number_v1(to_jsonb(U&'\00A0\FEFF1\FEFF'::text)),1::double precision,'NBSP and BOM numeric boundaries match Number trim');
select throws_ok($q$select dashboard_private.withdrawal_metadata_number_v1('"1e-999"')$q$,'22023','withdrawal_schedule_metadata_unsupported','binary64 underflow is explicit unsupported rather than skipped weekday');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 '{"schedule":"월19~21","schedule_plan":{"selectedDays":["1e-999"],"sessions":[{"date":"2026-11-01","hours":3},{"date":"2026-11-02","hours":2}]}}','2026-11-02'),
 '{"completed_lesson_hours":"","four_week_lesson_hours":""}'::jsonb,'unrepresentable metadata cannot silently select a different weekly basis');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 '{"schedule":"월수19~21","schedule_plan":{"sessions":[{"id":"source-index:1","date":"2026-11-02","sessionNumber":1},{"date":"2026-11-04","sessionNumber":2}]}}','2026-11-04'),
 '{"completed_lesson_hours":"2","four_week_lesson_hours":"16"}'::jsonb,'implicit source IDs retain existing first matching identity behavior');
select is(dashboard_private.withdrawal_first_scalar_v1('{"id":1.00}',array['id','sessionId']),'1','ordinary numeric identity has JS-compatible canonical text');
select throws_ok($q$select dashboard_private.withdrawal_first_scalar_v1('{"id":9007199254740992}',array['id','sessionId'])$q$,'22023','withdrawal_schedule_metadata_unsupported','ambiguous numeric identity cannot silently change grouping');
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 jsonb_build_object('schedule','월'||ws||'19'||ws||'~'||ws||'21','schedule_plan',
 '{"selectedDays":[1],"sessions":[{"date":"2026-11-02","state":"active"}]}'::jsonb),'2026-11-02'),
 '{"completed_lesson_hours":"2","four_week_lesson_hours":"8"}'::jsonb,'schedule parsing uses the fixed JS whitespace set: '||label)
 from (values (U&'\00A0','NBSP'),(U&'\FEFF','BOM'),(U&'\000B','vertical tab')) whitespace(ws,label);
select is(dashboard_private.calculate_teacher_withdrawal_hours_v1(
 jsonb_build_object('schedule',U&'월\008519\0085~\008521','schedule_plan',
 '{"selectedDays":[1],"sessions":[{"date":"2026-11-02","state":"active"}]}'::jsonb),'2026-11-02'),
 '{"completed_lesson_hours":"1","four_week_lesson_hours":"4"}'::jsonb,'U+0085 is not JavaScript whitespace and cannot invent a schedule duration');
select * from finish();
rollback;
